const rawUrl = window.location.href;
const normalizedUrl = decodeURIComponent(rawUrl);
const normalizedPrefix = decodeURIComponent('file:///path/to/user/Calibre%20书库');
const contents = document.querySelectorAll('.calibreEbookContent');
const content = contents.length === 1 ? contents[0] : null;
if (!normalizedUrl.startsWith(normalizedPrefix)) throw new Error('Calibre file URL prefix mismatch');
if (!content) throw new Error(`Expected exactly one .calibreEbookContent, found ${contents.length}`);

for (const id of [
  'automa-calibre-reader-style-v3',
  'automa-calibre-reader-style-v4',
  'automa-calibre-reader-content-style-v5',
  'automa-calibre-reader-panel-style-v5',
  'automa-calibre-reader-panel-v5',
  'automa-calibre-reader-toggle-v5'
]) document.getElementById(id)?.remove();

const contentStyle = document.createElement('style');
contentStyle.id = 'automa-calibre-reader-content-style-v5';
contentStyle.textContent = `
  html, body { width: 100% !important; min-width: 0 !important; margin: 0 !important; padding: 0 !important; background: #fff !important; overflow-x: hidden !important; }
  .calibreMain { width: 100% !important; margin: 0 auto !important; padding: 0 !important; background: #fff !important; }
  .calibreEbookContent { display: block !important; width: min(80vw, 1100px) !important; max-width: calc(100vw - 48px) !important; margin-left: auto !important; margin-right: auto !important; box-sizing: border-box !important; background: #fff !important; overflow-wrap: anywhere !important; }
  .calibreEbookContent img, .calibreEbookContent svg, .calibreEbookContent video, .calibreEbookContent canvas { display: block !important; max-width: 100% !important; width: auto !important; height: auto !important; object-fit: contain !important; }
  .calibreMeta, .calibreToc, .calibreEbNav, .calibreEbNavTop { display: none !important; }
  @media (max-width: 720px) { .calibreEbookContent { width: calc(100vw - 24px) !important; max-width: calc(100vw - 24px) !important; padding: 16px !important; } }
`;
document.head.appendChild(contentStyle);

const panelStyle = document.createElement('style');
panelStyle.id = 'automa-calibre-reader-panel-style-v5';
panelStyle.textContent = `
  #automa-calibre-reader-panel-v5 { position: fixed; top: 0; right: 0; width: 300px; height: 100vh; z-index: 2147483000; overflow: auto; box-sizing: border-box; padding: 16px; color: #1f2937; background: rgba(255,255,255,.98); border-left: 1px solid #d1d5db; box-shadow: -4px 0 16px rgba(0,0,0,.12); font: 14px/1.5 system-ui, sans-serif; }
  #automa-calibre-reader-panel-v5[hidden] { display: none !important; }
  #automa-calibre-reader-toggle-v5 { position: fixed; top: 16px; right: 300px; z-index: 2147483001; border: 1px solid #9ca3af; border-radius: 6px; padding: 6px 9px; color: #111827; background: #fff; cursor: pointer; }
  #automa-calibre-reader-panel-v5 h2, #automa-calibre-reader-panel-v5 h3 { margin: 0 0 10px; color: #111827; }
  #automa-calibre-reader-panel-v5 section { margin-bottom: 18px; }
  #automa-calibre-reader-panel-v5 .automa-v5-nav { display: flex; gap: 8px; flex-wrap: wrap; }
  #automa-calibre-reader-panel-v5 button, #automa-calibre-reader-panel-v5 a { color: #1d4ed8; }
  #automa-calibre-reader-panel-v5 button { cursor: pointer; border: 1px solid #cbd5e1; border-radius: 4px; padding: 5px 8px; background: #f8fafc; }
  #automa-calibre-reader-panel-v5 ul { margin: 0; padding-left: 18px; }
  #automa-calibre-reader-panel-v5 li { margin: 5px 0; }
  #automa-calibre-reader-panel-v5 .automa-v5-meta { white-space: pre-wrap; overflow-wrap: anywhere; }
  @media (max-width: 720px) { #automa-calibre-reader-panel-v5 { width: min(86vw, 300px); } #automa-calibre-reader-toggle-v5 { right: min(86vw, 300px); } }
`;
document.head.appendChild(panelStyle);

const panel = document.createElement('aside');
panel.id = 'automa-calibre-reader-panel-v5';
panel.setAttribute('aria-label', 'Calibre 阅读控制面板');
const toggle = document.createElement('button');
toggle.id = 'automa-calibre-reader-toggle-v5';
toggle.type = 'button';
toggle.textContent = '隐藏面板';
toggle.setAttribute('aria-expanded', 'true');
const title = document.querySelector('.calibreMetaTitle')?.textContent.trim() || document.title;
const author = document.querySelector('.calibreMetaAuthor')?.textContent.trim() || '';
const prev = document.querySelector('.calibreEbNavTop a.calibreAPrev');
const next = document.querySelector('.calibreEbNavTop a.calibreANext');
const toc = document.querySelectorAll('.calibreToc a');
const section = (heading, contentNode) => { const s=document.createElement('section'); const h=document.createElement('h3'); h.textContent=heading; s.append(h, contentNode); return s; };
const meta = document.createElement('div'); meta.className='automa-v5-meta'; meta.textContent = [title, author].filter(Boolean).join('\n');
const switchLabel = document.createElement('label'); const switchInput=document.createElement('input'); switchInput.type='checkbox'; switchInput.checked=true; switchLabel.append(switchInput, document.createTextNode(' 风格控制（开启）'));
const nav = document.createElement('div'); nav.className='automa-v5-nav';
for (const link of [prev, next]) if (link) { const button=document.createElement('button'); button.type='button'; button.textContent=link.textContent.trim(); button.addEventListener('click',()=>{ window.location.href=link.href; }); nav.appendChild(button); }
const tocList=document.createElement('ul');
for (const link of toc) { const li=document.createElement('li'); const a=document.createElement('a'); a.href=link.href; a.textContent=link.textContent.trim(); li.appendChild(a); tocList.appendChild(li); }
panel.append(section('风格控制', switchLabel), section('书籍信息', meta), section('页面导航', nav), section('目录', tocList));
document.body.append(panel, toggle);
const styleToggle = (enabled) => { contentStyle.disabled = !enabled; switchLabel.lastChild.textContent = enabled ? ' 风格控制（开启）' : ' 风格控制（关闭）'; };
switchInput.addEventListener('change', () => styleToggle(switchInput.checked));
toggle.addEventListener('click', () => { const hidden = panel.hasAttribute('hidden'); panel.toggleAttribute('hidden', !hidden); toggle.textContent = hidden ? '隐藏面板' : '显示面板'; toggle.style.right = hidden ? '300px' : '8px'; toggle.setAttribute('aria-expanded', String(hidden)); });
automaNextBlock();
